{
  "tools": [
    {
      "name": "set_tool_tier",
      "description": "Explicit tier override for the current session. Narrows or widens the exposed tool list to 'core' / 'standard' / 'full'. Prefer plan_turn(model=...) for routine per-task use; use set_tool_tier only for an explicit override (e.g. escalate to 'full' after a capability-gated failure). A narrowing that costs more than it saves is refused.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "tier": {
            "type": "string",
            "enum": [
              "core",
              "standard",
              "full"
            ]
          }
        },
        "required": [
          "tier"
        ]
      },
      "annotations": {
        "readOnlyHint": false,
        "openWorldHint": false
      }
    },
    {
      "name": "announce_model",
      "description": "Agent self-reports its active model identifier. Server resolves to a tier via model_tier_map (fuzzy: normalize → exact → glob → substring → '*' → 'full') and narrows the exposed tool list accordingly. Idempotent: a second call with the same model is a cheap no-op. Prefer calling plan_turn(model=...) for routine per-task use; use announce_model as a fallback when plan_turn is not appropriate for the current task.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "model": {
            "type": "string",
            "description": "Your active model identifier, e.g. 'claude-haiku-4-5'."
          }
        },
        "required": [
          "model"
        ]
      },
      "annotations": {
        "readOnlyHint": false,
        "openWorldHint": false
      }
    },
    {
      "name": "jcodemunch_guide",
      "description": "Return the version-current CLAUDE.md / AGENT.md policy snippet for jcodemunch-mcp — the same text produced by `jcodemunch-mcp claude-md --generate`. Lets an agent keep a one-line CLAUDE.md (e.g. \"Call jcodemunch_guide and strictly follow its instructions.\") instead of pasting a static snippet that drifts from the installed version. Idempotent, no repo context required. Matches the active tool surface, tier and disabled_tools — list 'jcodemunch_guide' in disabled_tools to hide it.",
      "inputSchema": {
        "type": "object",
        "properties": {}
      },
      "annotations": {
        "readOnlyHint": true,
        "openWorldHint": false
      }
    },
    {
      "name": "order",
      "description": "Dispatch any jcodemunch action by name: order(action, args). The single-verb front door to the full tool catalog. Read-only by default — actions that change index/session state require allow_state_change=true, and execution/file-write verbs are refused. For exploration questions ('how does X work'), order('get_ranked_context', {repo, query, token_budget}) answers in ONE call — prefer it over chained search/outline/source hops; add compress=true to fit more symbols in the same budget. Call 'menu' to discover actions, or 'route' to pick one from a task.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "description": "Name of the catalog action to run (e.g. 'search_symbols')."
          },
          "args": {
            "type": "object",
            "description": "Arguments for that action, exactly as you'd pass them directly.",
            "default": {}
          },
          "allow_state_change": {
            "type": "boolean",
            "description": "Opt in to dispatching an index/session state-changing action (e.g. index_repo).",
            "default": false
          }
        },
        "required": [
          "action"
        ]
      },
      "annotations": {
        "readOnlyHint": false,
        "openWorldHint": true
      }
    },
    {
      "name": "menu",
      "description": "Discover catalog actions without keeping the full tool catalog resident: menu(query?). Returns compact rows (action, summary, required args, state_changing). With no query, lists the catalog. Pair with 'order' to dispatch the chosen action.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Optional. Keywords describing what you want to do; ranks matching actions."
          },
          "limit": {
            "type": "integer",
            "description": "Max actions to return.",
            "default": 25
          }
        }
      },
      "annotations": {
        "readOnlyHint": true,
        "openWorldHint": false
      }
    },
    {
      "name": "route",
      "description": "Map a natural-language task to the best catalog action(s): route(task, repo?, execute?). Returns ranked recommendations with ready-to-run argument templates. With execute=true, dispatches the top recommendation and returns its result in the same call, collapsing discover-then-call into one round-trip. Recommends assemble_task_context / plan_turn for context-gathering intents.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "task": {
            "type": "string",
            "description": "What you're trying to do, in plain language."
          },
          "repo": {
            "type": "string",
            "description": "Repository identifier (required to execute repo-scoped actions)."
          },
